#!/usr/bin/env node
'use strict';const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');const ROOT=path.resolve(__dirname,'..'),PAGE=path.join(ROOT,'tools/crop-yield/index.html'),JSON_FILE=path.join(ROOT,'data/agriculture/crop-yield-tool-data.json'),JS_FILE=path.join(ROOT,'data/agriculture/crop-yield-tool-data.js');
function extract(s){const a=s.indexOf('var CROP_DATA='),b=s.indexOf('function onCropChange()',a);if(a<0||b<0)throw new Error('Crop Yield Tool data markers missing');const c={};vm.createContext(c);vm.runInContext(s.slice(a,b),c);return{schemaVersion:1,crops:JSON.parse(JSON.stringify(c.CROP_DATA)),symbols:JSON.parse(JSON.stringify(c.SYMBOLS)),presets:JSON.parse(JSON.stringify(c.PRESETS))}}
function browser(d){return`(function(root,factory){'use strict';var data=factory();if(typeof module==='object'&&module.exports)module.exports=data;if(root)root.CROP_YIELD_TOOL_DATA=data;}(typeof window!=='undefined'?window:globalThis,function(){return ${JSON.stringify(d,null,2)};}));\n`}
function run(){const d=fs.existsSync(JSON_FILE)?JSON.parse(fs.readFileSync(JSON_FILE,'utf8')):extract(fs.readFileSync(PAGE,'utf8'));fs.writeFileSync(JSON_FILE,JSON.stringify(d,null,2)+'\n');fs.writeFileSync(JS_FILE,browser(d));console.log(`Crop Yield Tool data owner: ${Object.keys(d.crops).length} crops, ${Object.keys(d.symbols).length} currencies, ${d.presets.length} presets`)}if(require.main===module)run();module.exports={extract,browser};
